package httpapi

const queryPage = `<!doctype html>
<html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>{{.ServiceName}}</title>
<style>body{margin:0;font-family:Arial,"Microsoft Yahei",sans-serif;background:#f4f8fc;color:#17324d}.bar{background:#0b5cab;color:white;padding:20px 8%;font-size:22px;font-weight:600}.wrap{max-width:860px;margin:42px auto;padding:0 24px}.panel{background:white;border:1px solid #d6e2ef;border-radius:6px;padding:28px;box-shadow:0 4px 14px #1d4f7a12}label{display:block;font-size:14px;margin-bottom:6px;color:#54708c}input{width:100%;box-sizing:border-box;padding:12px;border:1px solid #abc0d4;border-radius:4px;font-size:16px;margin-bottom:18px}button{background:#0b5cab;border:0;color:#fff;padding:12px 24px;border-radius:4px;font-size:16px;cursor:pointer}.result{margin-top:24px;padding:18px;background:#f6faff;border-left:4px solid #0b5cab}.missing{border-left-color:#d97706}.muted{color:#54708c;font-size:14px}</style></head>
<body><div class="bar">{{.ServiceName}}</div><main class="wrap"><section class="panel"><h1>延保查询</h1><p class="muted">输入购买手机号和设备序列号，查询延保及服务网点。</p><form action="/warranty/query" method="get"><label>购买手机号</label><input name="phone" value="{{.Phone}}" placeholder="11位手机号" required><label>设备序列号</label><input name="serial" value="{{.Serial}}" placeholder="设备序列号" required><button type="submit">查询延保</button></form>{{if .Result}}<div class="result {{if not .Found}}missing{{end}}">{{if .Found}}<h2>{{.Result.Message}}</h2><p>设备：{{.Result.Record.SerialNumber}}</p><p>品类：{{.Result.Record.Category}}　购买渠道：{{.Result.Record.PurchaseChannel}}</p><p>到期日：{{.Result.Record.ExpiryDate}}</p><p>服务网点：{{range .Result.ServicePoints}}{{.Name}} {{end}}</p>{{else}}<h2>未找到延保记录</h2><p>请核对手机号和序列号，或联系客服 {{.Hotline}} 进行人工核对。</p>{{end}}</div>{{end}}</section></main></body></html>`
